def bidualEvaluate (f : StrongDual 𝕜 X) : Bidual 𝕜 X →L[𝕜] 𝕜 := by
  let L : Bidual 𝕜 X →ₗ[𝕜] 𝕜 :=
    { toFun := fun z => z f
      map_add' := fun _ _ => rfl
      map_smul' := fun _ _ => rfl }
  exact L.mkContinuous ‖f‖ (fun z => by simpa only [mul_comm] using z.le_opNorm f)

